class RevaXtaInstruction_INPW_l2rus extends XtaInstruction {
    RevaXtaInstruction_INPW_l2rus(int opcode, int pc) {
        super("INPW_l2rus", opcode, pc, 4, false, true);
    }

    public void execute(MachineState state) {
        state.m_op1Fld = decode3OpDst(state.m_opcode);
        state.m_op2Fld = decode3OpSrc1(state.m_opcode);
        state.m_op3 = new Expression(decode3OpSrc2(state.m_opcode));
        state.m_op2 = new Expression(state.readRegister(state.m_op2Fld));
        int ranges[][] = {{32, 32}, {1, 9}, {16, 16}, {24, 24}};
        int mapsTo[][] = {{0, 0}, {1, 9}, {10, 10}, {11, 11}};
        state.m_op3 = reverseMap(state.m_op3, 4, ranges, mapsTo);
        INPW(state);
        state.writeRegister(state.m_op1Fld, state.m_op1);
    }

    public String getOperandString() {
        int opcode = getOpcode();
        int ranges[][] = {{32, 32}, {1, 9}, {16, 16}, {24, 24}};
        int mapsTo[][] = {{0, 0}, {1, 9}, {10, 10}, {11, 11}};
        return String.format("r%d, res[r%d], i 0x%x",
            decode3OpDst(opcode),
            decode3OpSrc1(opcode),
            reverseMap(decode3OpSrc2(opcode), 4, ranges, mapsTo));
    }
}

