class RevaXtaInstruction_MKMSK_rus extends XtaInstruction {
    RevaXtaInstruction_MKMSK_rus(int opcode, int pc) {
        super("MKMSK_rus", opcode, pc, 2, false, false);
    }

    public void execute(MachineState state) {
        state.m_op1Fld = decode2OpSrcDst(state.m_opcode);
        state.m_op2 = new Expression(decode2OpSrc(state.m_opcode));
        int ranges[][] = {{32, 32}, {1, 9}, {16, 16}, {24, 24}};
        int mapsTo[][] = {{0, 0}, {1, 9}, {10, 10}, {11, 11}};
        state.m_op2 = reverseMap(state.m_op2, 4, ranges, mapsTo);
        MKMSK(state);
        state.writeRegister(state.m_op1Fld, state.m_op1);
    }

    public String getOperandString() {
        int opcode = getOpcode();
        int ranges[][] = {{32, 32}, {1, 9}, {16, 16}, {24, 24}};
        int mapsTo[][] = {{0, 0}, {1, 9}, {10, 10}, {11, 11}};
        return String.format("r%d, i 0x%x",
            decode2OpSrcDst(opcode),
            reverseMap(decode2OpSrc(opcode), 4, ranges, mapsTo));
    }
}

